mapper.sql:
where a.role in ('ADMIN','STAFF','SCREEN')
and a.role=#{query.role}
and a.enabled=#{query.enabled}
and (a.username like concat('%',#{query.keyword},'%') or a.display_name like concat('%',#{query.keyword},'%') or w.name like concat('%',#{query.keyword},'%') or w.canteen_name like concat('%',#{query.keyword},'%'))

mapper.select:
select a.user_id,a.username,a.display_name,a.role,a.window_id,a.enabled,w.name window_name,w.canteen_name,u.create_time
from campus_account a join user u on u.id=a.user_id left join campus_window w on w.id=a.window_id
 order by a.user_id limit #{query.pageSize} offset #{query.offset}

mapper.sql:
where 1=1
and co.window_id=#{query.windowId}
and o.status in (2,3,4)and o.status=#{query.state}
and s.service_date >=#{query.fromDate}
and s.service_date <=#{query.toDate}
and (a.display_name like concat('%',#{query.keyword},'%') or a.username like concat('%',#{query.keyword},'%') or o.number like concat('%',#{query.keyword},'%') or w.name like concat('%',#{query.keyword},'%') or w.canteen_name like concat('%',#{query.keyword},'%') or exists(select 1 from order_detail od where od.order_id=o.id and od.name like concat('%',#{query.keyword},'%')))

mapper.select:

order by case o.status when 2 then 0 when 3 then 1 when 4 then 2 when 1 then 3 when 5 then 4 else 5 end,
case when o.status in (2,3,4) then timestamp(s.service_date,s.end_time) end asc,o.id desc
limit #{query.pageSize} offset #{query.offset}
